import {readFileSync,writeFileSync,statfsSync,statSync} from 'node:fs';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {OwnedDatabase} from '../src/infrastructure/database/owned-database';
import {createSchema} from '../src/infrastructure/database/schema';
import {rebuildProjections,readMemoryEventsWithReport} from '../src/infrastructure/database/event-log';
import {recoverPendingProjections,createProjectedEventWriter} from '../src/infrastructure/database/projection-recovery';
import {MemoryEventEnvelope} from '../src/domain/entities/memory-event';
import {discoverInventory,sourceHash} from '../scripts/quality-inventory';
const free=statfsSync(process.cwd());if(free.bavail*free.bsize<536870912)throw Error('Synthetic cost run requires512MiB free');
const inputs=discoverInventory(process.cwd()).files.map(f=>({path:f.path,sourceHash:f.sourceHash})),runs=[];
for(const count of [10,100,1000]){
 const storage=createOwnedTestDirectory('memory-replay-cost-'),log=join(storage.dir,'events-synthetic.jsonl'),db=new OwnedDatabase(join(storage.dir,'synthetic.db'));
 try {
  createSchema(db);db.exec('PRAGMA journal_mode=WAL');
  writeFileSync(log,Array.from({length:count},(_,i)=>JSON.stringify({uuid:'cost-'+i,type:'learning',project:'synthetic',content:'Synthetic replay record '+i,observedAt:'2026-01-01T00:00:00Z'})).join('\n')+'\n');
  const start=performance.now();await rebuildProjections(db,log);const baselineMs=performance.now()-start;
  const noopMs=[];
  for(let i=0;i<3;i++){const start=performance.now(),result=await recoverPendingProjections(db,log);noopMs.push(performance.now()-start);if(result.rebuilt||result.pending)throw Error('Unexpected pending source');}
  const first=(await readMemoryEventsWithReport(log)).events[0]!,time=new Date('2026-01-02T00:00:00Z');
  const event=MemoryEventEnvelope.create({...first.toJSON(),eventId:'cost-added',sequence:count+1,occurredAt:time,observedAt:time,payload:{fact:{uuid:'cost-added',type:'learning',project:'synthetic',content:'Added synthetic fact',observedAt:time.toISOString()}}});
  const rssBefore=process.memoryUsage().rss,writeStart=performance.now();await createProjectedEventWriter(db,log)(event);const writeMs=performance.now()-writeStart;
  using facts=db.prepare<{n:number},[]>('SELECT COUNT(*) AS n FROM facts');if(facts.get()?.n!==count+1)throw Error('Wrong fact count');
  runs.push({eventsBefore:count,sourceBytesAfter:statSync(log).size,baselineMs,noopMs,writeMs,rssBefore,rssAfter:process.memoryUsage().rss});
 }finally{db.close();storage.cleanup();}
}
for(const row of inputs)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Source changed '+row.path);
writeFileSync('.git/q100-callers-cost.json',JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,platform:process.platform,arch:process.arch,command:[process.execPath,'.git/q100-callers-cost.ts'],sourceInputs:inputs,runs,limits:'Small synthetic observations on this machine, not supported-platform latency guarantees. Connection creation is excluded from writer/noop times. RSS snapshots are not peak memory. Other machine load is uncontrolled. No production corpus or provider is used.',source:readFileSync('.git/q100-callers-cost.ts','utf8')},null,2)+'\n');
console.log(JSON.stringify(runs));

